def offer_text(vars):
    email_ok = sget(vars, "email_ok") == "yes"
    change_ok = sget(vars, "change_ok", "yes") == "yes"
    if email_ok and change_ok:
        return fill("offer_both")
    if change_ok:
        return fill("offer_change_only")
    if email_ok:
        return fill("offer_email_only")
    return ""


