def week_options(vars):
    rf = (POL.get("response_fields") or {}).get("cycle_get") or {}
    lo = int(rf.get("week_min") or 1)
    hi = int(rf.get("week_max") or 4)
    cur = iget(vars, "cur_week", 0)
    return [w for w in range(lo, hi + 1) if w != cur]


