        say_exit(vars, (fill('document_unavailable') + ' ' + fill('to_menu')).strip(), 'menu')
    else:
        say_exit(vars, fill('service_error_transfer'), 'service_error')
except Exception as _e:
    vars['code_error'] = str(_e)
    if not vars.get('route'):
        vars['route'] = 'error'

