        else:
            d = {}
            for k in ["cardNumber", "cardNumberLast4", "productName", "statementDate", "lastPayDate", "nextStatementDate", "nextLastPayDate", "debtTL", "debtUSD", "debtEUR", "debtGBP", "statementPaymentStatus", "totalDebtPaymentStatus", "automaticPaymentFlag"]:
                v = mapped(vars, 'bal__' + k)
                if v is not None and v != {}:
